function refuseNamedCode(template) {
  const { commands, inCode, inExpansion } = commandsOf(template);
  const fix = 'The story is data: read SUITE_TITLE, SUITE_KEY or SUITE_BRANCH in your own program (process.env.SUITE_TITLE, os.environ) and use it there as data.';
  const refuse = (name, where, clause = 'where the shell would run it as code', more = '') => new Stop(`{${name}} cannot stand ${where}, ${clause}. ${fix}${more}`);
  if (inCode.length) throw refuse(inCode[0], 'inside $( ) or backticks');
  if (inExpansion.length) throw refuse(inExpansion[0], 'inside ${ }', 'where the shell may run it as code (a default or alternative holding a command, an array index)');
  const WRAPPERS = new Set(['command', 'builtin', 'exec', 'env', 'nohup', 'nice', 'sudo', 'time', 'timeout', 'xargs', 'stdbuf']);
  const RUNNERS = new Set(['eval', 'source', '.', 'trap', 'watch']);
  const KEYWORDS = new Set(['if', 'then', 'else', 'elif', 'while', 'until', 'do', '!', '{', '}']);
  const text = (word) => word.filter((part) => typeof part === 'string').join('');
  const nameOf = (word) => word.find((part) => typeof part !== 'string')?.name;
  const base = (word) => text(word).replace(/^.*\//, '').replace(/\.exe$/i, '');
  const assignment = (word) => /^[A-Za-z_]\w*=/.test(text(word));
  // How code is told from data for each interpreter. Its options come first and the first word that is no option is its
  // script, after which everything is data (`lenient`: the options are read anywhere before `--`, for npm). `code` letters
  // take the code: `joined`, the rest of the word if there is any, else the next word. `value` letters take a value (the
  // rest of the word, or the next word), `rest` letters one in the rest of the word, `file` letters a program file (awk
  // -f), `stop` letters end the options (python -m). A long option in `longCode` takes the code (`--eval=x` or the next
  // word), in `longValue` a value, in `longFile` a file. Where the code is a word, not a flag's (awk's program, deno
  // eval's text), it is the first word that is no option, unless a flag gave the program. `sub` is the subcommand to find first.
  const NODE_LONG = ['require', 'import', 'loader', 'experimental-loader', 'input-type', 'conditions', 'env-file', 'title'];
  const SPECS = [
    { is: /^(?:python|pypy|py)[\d.]*$/, code: 'c', joined: true, value: 'WX', stop: 'm', once: true },
    { is: /^(?:node|nodejs)$/, code: 'ep', value: 'rC', longCode: ['eval', 'print'], longValue: NODE_LONG },
    { is: /^bun$/, code: 'ep', value: 'rc', longCode: ['eval', 'print'], longValue: [...NODE_LONG, 'preload', 'cwd', 'config', 'port', 'define', 'tsconfig-override'] },
    { is: /^perl[\d.]*$/, code: 'eE', joined: true, value: 'I', rest: 'iMmFxCdDV' },
    { is: /^ruby[\d.]*$/, code: 'e', joined: true, value: 'CIrE', rest: 'FixWKT' },
    { is: /^php[\d.]*$/, code: 'rRBE', joined: true, value: 'dczfFtSH' },
    { is: /^deno$/, sub: /^eval$/, positional: 'code', value: 'cL', longValue: ['ext', 'config', 'import-map', 'cert', 'location', 'seed', 'v8-flags', 'lock', 'log-level'] },
    { is: /^(?:[gmn]?awk|original-awk)$/, code: 'e', joined: true, value: 'vFilW', file: 'f', longCode: ['source'], longFile: ['file'], longValue: ['assign', 'field-separator', 'include', 'load'], positional: 'program' },
    { is: /^npx$/, lenient: true, code: 'c', value: 'pw', longCode: ['call'], longValue: ['package', 'workspace'] },
    { is: /^npm$/, sub: /^(?:exec|x)$/, lenient: true, code: 'c', value: 'pw', longCode: ['call'], longValue: ['package', 'workspace'] },
  ];
  const scan = (spec, args) => {
    const found = [];
    let given = false;
    for (let i = 0; i < args.length; i++) {
      const word = args[i];
      const w = text(word);
      if (w === '--') break;
      if (!/^-./.test(w)) {
        if (spec.positional && !given) found.push({ word, flag: '' });
        if (spec.lenient) continue;
        break;
      }
      if (w.startsWith('--')) {
        const key = w.slice(2).split('=')[0];
        const inline = w.includes('=');
        if (spec.longCode?.includes(key)) {
          given = true;
          found.push({ word: inline ? word : args[++i], flag: w });
        } else if (spec.longFile?.includes(key)) {
          given = true;
          if (!inline) i++;
        } else if (spec.longValue?.includes(key) && !inline) i++;
        continue;
      }
      for (let c = 1; c < w.length; c++) {
        const ch = w[c];
        const last = c + 1 === w.length && !nameOf(word);
        if (spec.code?.includes(ch)) {
          given = true;
          found.push({ word: !last && (spec.joined || nameOf(word)) ? word : args[++i], flag: `-${ch}` });
          if (spec.once) return found;
          break;
        }
        if (spec.value?.includes(ch) || spec.file?.includes(ch)) {
          if (spec.file?.includes(ch)) given = true;
          if (last) i++;
          break;
        }
        if (spec.rest?.includes(ch)) break;
        if (spec.stop?.includes(ch)) return found;
      }
    }
    return found;
  };
  for (const cmd of commands) {
    let k = 0;
    while (cmd[k] && (KEYWORDS.has(text(cmd[k])) || assignment(cmd[k]))) k++;
    const start = k;
    // A wrapper starts the program that follows its options; that program is never the story's.
    while (cmd[k] && WRAPPERS.has(base(cmd[k]))) {
      const wrapper = base(cmd[k]);
      k++;
      while (cmd[k] && (/^-/.test(text(cmd[k])) || /^\d+$/.test(text(cmd[k])) || assignment(cmd[k]))) k += /^-[uCSPIdEnLsga]$/.test(text(cmd[k])) ? 2 : 1;
      if (cmd[k] && nameOf(cmd[k])) throw refuse(nameOf(cmd[k]), `as the program ${wrapper} starts`);
    }
    if (cmd[k] && RUNNERS.has(base(cmd[k]))) {
      const given = cmd.slice(k + 1).find(nameOf);
      if (given) throw refuse(nameOf(given), `as an argument of ${base(cmd[k])}, which runs its arguments as code`);
    }
    // A shell run with -c: the word after the flag is its code, wherever the shell stands in the command (env sh -c, xargs bash -c).
    for (let j = start; j < cmd.length; j++) {
      if (!/^(?:a?sh|bash|zsh|dash|ksh|mksh|csh|tcsh|fish|rbash)$/.test(base(cmd[j]))) continue;
      const flag = cmd.findIndex((word, f) => f > j && /^-[A-Za-z]*c[A-Za-z]*$/.test(text(word)) && !nameOf(word));
      if (flag > 0 && cmd[flag + 1] && nameOf(cmd[flag + 1])) throw refuse(nameOf(cmd[flag + 1]), `as the code of ${base(cmd[j])} -c`);
    }
    // An interpreter's code, wherever the interpreter stands (env python3 -c, timeout 5 node -e): see SPECS for what is code and what is data.
    for (let j = start; j < cmd.length; j++) {
      const prog = base(cmd[j]).replace(/\.cmd$/i, '');
      const spec = SPECS.find((one) => one.is.test(prog));
      if (!spec) continue;
      let args = cmd.slice(j + 1);
      let label = prog;
      if (spec.sub) {
        const sub = args.findIndex((word) => spec.sub.test(text(word)));
        if (sub < 0) continue;
        label = `${prog} ${text(args[sub])}`;
        args = args.slice(sub + 1);
      }
      for (const { word, flag } of scan(spec, args)) {
        if (!word || !nameOf(word)) continue;
        const where = flag ? `as the code of ${label} ${flag}` : `as the ${spec.positional} of ${label}`;
        throw refuse(nameOf(word), where, `where ${prog} would run it as code`, ' Or give it after the code, as an argument the code reads (process.argv, sys.argv, $ARGV, ARGV).');
      }
    }
    // find runs the words between -exec, -execdir, -ok or -okdir and its ; or + as a command: a name there is the command or its arguments.
    for (let j = start; j < cmd.length; j++) {
      if (base(cmd[j]) !== 'find') continue;
      for (let f = j + 1; f < cmd.length; f++) {
        if (!/^-(?:exec|execdir|ok|okdir)$/.test(text(cmd[f]))) continue;
        for (let a = f + 1; a < cmd.length && text(cmd[a]) !== ';' && !(text(cmd[a]) === '+' && text(cmd[a - 1]) === '{}'); a++) {
          if (nameOf(cmd[a])) throw refuse(nameOf(cmd[a]), `among the words find ${text(cmd[f])} runs as a command`, 'where find would run it as, or in, a command');
        }
      }
    }
  }
}

/**
 * A command's {names} as the shell's variables: "${SUITE_KEY}" for sh, as one word.
 * On Windows the shell is cmd, which reads %SUITE_KEY% before it parses the line, so a value holding & | < > ^ " or %NAME%
 * would be read as part of the command: there only {key} and {branch} (checked, plain) are put in a command, and any other
 * name (the story's {title}) is refused, saying to read the environment variable instead.
 */
// Unsure: that cmd expands %VAR% before it parses & | > ^ is from cmd's documented order of phases; not run on a real Windows.
function asVariables(template, platform = process.platform) {
  if (platform !== 'win32') return parseCommand(template).text;
  refuseNamedCode(template);
  return template.replace(/\{(\w+)\}/g, (_, k) => {
    const name = `SUITE_${k.toUpperCase()}`;
    if (!CHECKED.has(k)) {
      throw new Stop(
        `{${k}} cannot be used in a command on Windows: cmd.exe replaces %${name}% before it reads the line, so a & | < > ^ " or %NAME% in a story's text would run as part of the command. ` +
          `Read the environment variable ${name} in your own program instead (process.env.${name}, $env:${name}, os.environ), or the story's file in stories/; only {key} and {branch} can stand in a command.`,
      );
    }
    return `%${name}%`;
  });
}

/** Every command the pipeline gave, tried before any story is worked on: a {name} the shell cannot take stops the run at once, not after the crew's work. */
function checkCommands(env = process.env, platform = process.platform) {
  const all = [env.SUITE_CREW || 'claude -p "/stories {key}"', ...(env.SUITE_CHECKS ?? '').split('\n'), env.SUITE_PROPOSE, env.SUITE_AGAIN];
  for (const template of all) if (template) asVariables(template, platform);
}

// ---- Locks: one git ref a file, made by a push without force, so only one push can make it ----

const lockRef = (file) => `${LOCKS}/${file.replace(/[^A-Za-z0-9._/-]/g, '_')}`;

/** Every lock: its file, the story holding it, and since when. */
function locks() {
  const out = git('ls-remote', 'origin', `${LOCKS}/*`) ?? '';
  return out
    .split('\n')
    .filter(Boolean)
    .map((line) => {
      const [sha, ref] = line.split('\t');
      git('fetch', '-q', 'origin', `${ref}:${ref}`);
      // A lock freed and made again while it was read cannot be read: counted as new, never as stale.
      const [key = '?', at = String(Date.now()), agent = '?'] = (git('log', '-1', '--format=%s', sha) ?? '').split(' ').filter(Boolean);
      return { file: ref.slice(LOCKS.length + 1), ref, sha, key, at: Number(at) || Date.now(), agent };
    });
}

/** A file locked for a story: true when it holds it now (made, or already the story's own). */
function lock(file, key) {
  const ref = lockRef(file);
  const sha = git('commit-tree', EMPTY_TREE, '-m', `${key} ${Date.now()} ${AGENT}`);
  if (sha && git('push', '-q', 'origin', `${sha}:${ref}`) !== null) return true;
  const held = locks().find((l) => l.ref === ref);
  if (!held) return false;
  // A story's own lock is its agent's alone (two agents taking one story at once); a file's, the story's.
  if (held.key === key && (!file.startsWith('story/') || held.agent === AGENT)) return true;
  // A lock left by an agent that stopped: older than SUITE_LOCK_HOURS, taken over.
  if (Date.now() - held.at > STALE_MS) {
    say(`${file}: ${held.key}'s lock is stale; taken over`);
    // Only that lock: one another agent made since is left.
    if (git('push', '-q', `--force-with-lease=${ref}:${held.sha}`, 'origin', `:${ref}`) === null) return false;
    return lock(file, key);
  }
  return false;
}

/** Every lock a story holds, freed. */
function release(key) {
  for (const l of locks().filter((x) => x.key === key)) git('push', '-q', 'origin', `:${l.ref}`);
}

/** Waits for every file locked for the story; false when one stays held past SUITE_WAIT_MINUTES. */
async function lockAll(files, key) {
  const until = Date.now() + WAIT_MS;
  for (const file of files) {
    while (!lock(file, key)) {
      if (Date.now() > until) return false;
      const by = locks().find((l) => l.ref === lockRef(file))?.key ?? 'another story';
      say(`${key}: waits for ${file} (${by} holds it until its pull request merges)`);
      await sleep(POLL_MS);
    }
  }
  return true;
}

// ---- Which pages a story touches, from its words, to keep two stories off one page at once ----

/** The suite's page classes: each file under a folder named pages, with the words of its name. */
function pageFiles() {
  const files = (git('ls-files') ?? '').split('\n').filter((f) => /(^|\/)pages\//.test(f) && /\.(java|ts|js|txt)$/.test(f));
  return files.map((f) => {
    const name = f
      .split('/')
      .pop()
      .replace(/\.\w+$/, '')
      .replace(/(Page|Elements|Actions|Tasks)$/, '');
    return {
      file: f,
      words: name
        .replace(/([a-z])([A-Z])/g, '$1 $2')
        .toLowerCase()
        .split(/[\s_-]+/)
        .filter(Boolean),
    };
  });
}

/** The page files a story's words name. */
function pagesOf(text, pages) {
  const words = new Set(text.toLowerCase().split(/[^a-z0-9]+/));
  return pages.filter((p) => p.words.length && p.words.every((w) => words.has(w))).map((p) => p.file);
}

// ---- What a story became ----

/** A story's file among some files: its done file and its new one. */
const storyOf = (names, key) => names.find((f) => f.toUpperCase().startsWith(`${key} `) || f.toUpperCase() === `${key}.TXT`);

/** What the crew decided from a done file's text: implemented, or waiting on an answer. */
function fromDone(text) {
  // The crew's note starts a line: the same marker Jira's own text is never left to produce (sync.mjs writes it with "> " in front).
  const at = [...text.matchAll(/^---- IMPLEMENTED/gm)].map((m) => m.index).pop() ?? -1;
  if (at < 0) return null;
  // The crew's note alone, as sync.mjs reads it (its noteEnd): up to the line before the next "----" or "Answer:" line.
  const first = text.indexOf('\n', at);
  const rest = first < 0 ? '' : text.slice(first);
  const end = rest.search(/(?<=[\n\r\u2028\u2029])(?:----|[ \t]*answer:)/i);
  const note = end < 0 ? rest : rest.slice(0, end);
  return /^Not implemented:(?!\s*none\b)/im.test(note) ? 'waiting' : 'implemented';
}

/** What the crew decided for the story in this working copy: implemented, waiting, pushed back, or nothing. */
function decided(key) {
  const done = join(ROOT, 'stories', 'done');
  const file = existsSync(done) ? storyOf(readdirSync(done), key) : null;
  const outcome = file ? fromDone(readFileSync(join(done, file), 'utf8')) : null;
  if (outcome) return outcome;
  return sync('pending').out.includes(`"key":"${key}"`) ? 'pushed back' : 'nothing';
}

/** git, in the bare repository the crew's bundle is read in (publish makes it; null before). */
let READER = null;
/** The seconds one call that reads a bundle may take (a team with a very large suite raises it in the pipeline's settings). */
const readSeconds = () => Number(process.env.SUITE_BUNDLE_READ_SECONDS) || BUNDLE_READ_SECONDS;
/** git in the reader, with a time limit: a bundle can be made to take for ever to unpack. */
const peekRaw = (args, input, bytes, config) => gitRaw(READER, args, input, { ms: readSeconds() * 1000, bytes, config });
const peek = (...args) => peekRaw(args)?.trim() ?? null;
/** The sentence for a read that failed: its time ran out, or git could not read it. */
const couldNot = (what) => (CUT_SHORT === 'ETIMEDOUT' ? `git took longer than ${readSeconds()} second${readSeconds() === 1 ? '' : 's'} to read ${what}` : `git could not read ${what}`);

/** What a branch from the crew says the story became, read from its own files: data, never its say-so alone. */
function decidedIn(ref, key, said) {
  const names = (dir) => (peek('ls-tree', '--name-only', `${ref}:${dir}`) ?? '').split('\n').filter(Boolean);
  const done = storyOf(names('stories/done'), key);
  const outcome = done ? fromDone(peek('show', `${ref}:stories/done/${done}`) ?? '') : null;
  if (said === 'implemented' || said === 'waiting') return outcome === said ? said : 'nothing';
  if (said === 'pushed back') return storyOf(names('stories/new'), key) ? said : 'nothing';
  return said === 'checks failed' ? said : 'nothing';
}

/** The files a story changed since `base` that existed before it: the ones another story could also change. */
function sharedSince(base, ref = '') {
  return (peek('diff', '--name-only', '--no-renames', base, ...(ref ? [ref] : [])) ?? '')
    .split('\n')
    .filter((f) => f && !f.startsWith('stories/') && !f.startsWith('jira-loop/') && peek('cat-file', '-e', `${base}:${f}`) !== null);
}

/** The working copy back on a commit, nothing of the last story left. */
function resetTo(commit) {
  git('checkout', '-q', '-B', 'work', commit);
  git('reset', '-q', '--hard', commit);
  git('clean', '-qfd', '-e', 'secrets/', '-e', 'jira-loop/run/');
}

/** The newest main, in this folder. */
function fresh() {
  git('fetch', '-q', 'origin', 'main');
  resetTo('origin/main');
}

// ---- The three jobs ----

/** What a run claimed: the commit it started from, and each story (its key, title, agent, file), from this run's folder or the pipeline. */
function readClaimed() {
  try {
    if (process.env.SUITE_CLAIMED) return JSON.parse(Buffer.from(process.env.SUITE_CLAIMED, 'base64').toString('utf8'));
    return existsSync(CLAIMED) ? JSON.parse(readFileSync(CLAIMED, 'utf8')) : { base: null, stories: [], held: [] };
  } catch {
    throw new Stop(`what the claim job handed on (${process.env.SUITE_CLAIMED ? 'SUITE_CLAIMED' : 'jira-loop/run/claimed.json'}) is not readable: run the claim job again.`);
  }
}

/** claim: the ready stories, no two naming the same page, a few for each agent; claimed in Jira, their pages locked. */
function claim(skip = () => false) {
  fresh();
  const q = sync('queue');
  if (q.code !== 0) {
    say(q.out);
    return 1;
  }
  // Jira not set up: sync says so, and there is nothing to claim.
  // The list is what sync wrote to stdout; a sentence on the other stream (a card skipped, say) follows it in out.
  const ready = q.out.startsWith('[') ? JSON.parse(q.json) : [];
  if (!q.out.startsWith('[')) say(q.out);
  const agents = Math.max(1, Number(process.env.SUITE_AGENTS || 1));
  const room = agents * Math.max(1, Number(process.env.SUITE_STORIES || 3));
  const pages = pageFiles();
  const held = new Set(locks().map((l) => l.file));
  const taken = [];
  // Ready, but a page of theirs held by a story not merged yet: for a later run.
  let blocked = 0;
  for (const s of ready) {
    if (taken.length >= room) break;
    if (!KEY.test(s.key) || skip(s.key)) continue;
    const named = pagesOf(s.text, pages);
    if (named.some((f) => held.has(f))) {
      blocked++;
      continue;
    }
    // The story's own lock first, then its pages', then the claim in Jira: two agents never take one story, however
    // close, and a page another story took meanwhile leaves this one for the next run (claiming never waits: two
    // claims each waiting on a page the other holds would wait for ever).
    if (!lock(`story/${s.key}`, s.key)) continue;
    if (!named.every((f) => lock(f, s.key)) || sync('take', s.key).code !== 0) {
      blocked++;
      release(s.key);
      continue;
    }
    for (const f of named) held.add(f);
    // Where take wrote it: stories/new/, or stories/done/ with the answers it waited on.
    const [dir, name] = ['new', 'done'].map((d) => [d, existsSync(join(ROOT, 'stories', d)) ? storyOf(readdirSync(join(ROOT, 'stories', d)), s.key) : null]).find(([, n]) => n);
    const agent = `agent-${(taken.length % agents) + 1}`;
    taken.push({ key: s.key, title: s.text.split('\n')[0], agent, file: { dir, name, text: readFileSync(join(ROOT, 'stories', dir, name), 'utf8') } });
    say(`${s.key}: taken for ${agent} (${s.text.split('\n')[0]})`);
  }
  // The commit the crew starts from, read once the pages are locked: a page held cannot change on main after it.
  git('fetch', '-q', 'origin', 'main');
  const base = git('rev-parse', 'origin/main') ?? git('rev-parse', 'HEAD');
  const claimed = { base, stories: taken, blocked, held: locks().map((l) => ({ file: l.file, key: l.key })) };
  mkdirSync(RUN, { recursive: true });
  writeFileSync(CLAIMED, `${JSON.stringify(claimed, null, 2)}\n`);
  // A pipeline hands the next jobs what was claimed (GitHub: the job's outputs).
  if (process.env.GITHUB_OUTPUT) {
    const agents = JSON.stringify([...new Set(taken.map((t) => t.agent))]);
    writeFileSync(process.env.GITHUB_OUTPUT, `any=${taken.length > 0}\nagents=${agents}\nclaimed=${Buffer.from(JSON.stringify(claimed)).toString('base64')}\n`, { flag: 'a' });
  }
  say(`claimed ${taken.length} ${taken.length === 1 ? 'story' : 'stories'}${taken.length ? '' : blocked ? `: ${blocked} ready, each waiting on a page another story holds until it merges` : ': nothing ready to take'}`);
  return 0;
}

/** crew: this agent's stories, each from the run's commit, its tests checked and committed as its branch; then the bundle. */
function crew() {
  checkCommands();
  const { base, stories } = readClaimed();
  const mine = stories.filter((s) => s.agent === AGENT && KEY.test(s.key));
  if (!mine.length) {
    say('no story for this agent in this run');
    return 0;
  }
  const branches = [];
  for (const { key, title, file } of mine) {
    if (basename(file.name) !== file.name || !['new', 'done'].includes(file.dir)) continue;
    resetTo(base);
    mkdirSync(join(ROOT, 'stories', file.dir), { recursive: true });
    writeFileSync(join(ROOT, 'stories', file.dir, file.name), file.text);
    const values = { key, title, branch: `stories/${key}` };
    if (shell(process.env.SUITE_CREW || 'claude -p "/stories {key}"', values, { crew: true }) !== 0) say(`${key}: the crew stopped with an error`);
    let outcome = decided(key);
    if (outcome === 'implemented') {
      for (const check of (process.env.SUITE_CHECKS ?? '').split('\n').filter(Boolean)) {
        if (shell(check, values, { crew: true }) !== 0) {
          outcome = 'checks failed';
          say(`${key}: checks failed (${check})`);
          break;
        }
      }
    }
    git('switch', '-q', '-C', values.branch);
    git('add', '-A', '--', '.', ':!jira-loop/reported.json', ':!jira-loop/run');
    git('commit', '-q', '--allow-empty', '-m', `${key}: ${title}`, '-m', `Outcome: ${outcome}`, '-m', `Tests written by the suite's crew (${AGENT}).`);
    branches.push(`refs/heads/${values.branch}`);
    say(`${key}: ${outcome}`);
  }
  mkdirSync(RUN, { recursive: true });
  const bundle = join(RUN, `${AGENT}.bundle`);
  if (git('bundle', 'create', bundle, ...branches) === null) {
    say('could not bundle the branches');
    return 1;
  }
  resetTo(base);
  say(`bundled ${branches.length} ${branches.length === 1 ? 'branch' : 'branches'}: ${bundle}`);
  return 0;
}

// ---- A crew's bundle: data to be read, never run ----
// The publish job holds the push token and Jira's; a bundle is the crew's, and so is every name, size and ref in it.
// It is fetched into a bare repository made for it (no template, so no hook; hooks and fsmonitor off in every git
// call), read with git's own plumbing, and never checked out.

/** A word of a path as a checkout on Windows or macOS would read it: invisible characters, an NTFS stream, trailing dots and spaces gone, lower case. */
const folded = (word) => word.replace(/\p{Cf}/gu, '').replace(/:.*$/s, '').replace(/[. ]+$/, '').toLowerCase();
/** The 8.3 short name NTFS gives a long one (.github: GITHUB~1): its first six letters, no dots, then ~ and a digit. */
const shortOf = (name) => name.replace(/[. ]/g, '').slice(0, 6);
/** A folded word is this name, or its 8.3 short name. */
const isName = (word, name) => word === name || ((m) => Boolean(m) && m[1] === shortOf(name))(/^([^.~]{1,6})~\d+(\.[^.]{0,3})?$/.exec(word));
/** A word git itself keeps: .git and every .git* name (.gitmodules, .gitattributes, .github, .gitlab-ci.yml), or the short name of one. */
const gitish = (word) => word.startsWith('.git') || /^git[^.~]{0,3}~\d+(\.[^.]{0,3})?$/.test(word);
/** A sentence's text from a name a crew chose: printable, short, every character Jira's markup reads (an image !x!, a macro {x}, a link) escaped with a backslash. */
const plain = (text) => String(text).slice(0, 80).replace(/[^\x20-\x7e]/g, '?').replace(/"/g, "'").replace(/[\\!*_+^~#?:{}[\]|-]/g, '\\$&');

/** Why a path in a crew's tree is refused (a checkout could write it outside the folder, or into .git), or null. */
function trick(path, mode) {
  if (/^([\\/]|[A-Za-z]:)/.test(path)) return 'an absolute path';
  const words = path.split(/[\\/]/);
  for (const word of words) {
    if (word === '.' || word === '..') return 'a . or .. in a path';
    if (word === '') return 'an empty name in a path';
    const f = folded(word);
    if (f === '') return 'a name of dots and spaces';
    if (isName(f, '.git')) return 'a .git name';
  }
  if (mode === '120000' && isName(folded(words.at(-1)), '.gitmodules')) return 'a .gitmodules symlink';
  return null;
}

/**
 * Whether a path in a crew's branch is something the pipeline runs with the secrets or reads as a setting: the pipeline files
 * (.github/, .gitlab-ci.yml, azure-*.yml), the loop itself (jira-loop/), the build files of the Java and Cypress suites
 * (pom.xml, .mvn/, mvnw, package.json, package-lock.json, .npmrc, cypress.config.*, tsconfig.json, Dockerfile), any .git* name,
 * and the folders Claude Code and the editor run hooks and tasks from (.claude/, .vscode/). Named as a checkout would read it.
 */
const PIPELINE_DIRS = ['.github', 'jira-loop', '.claude', '.vscode'];
const PIPELINE_FILES = ['.gitlab-ci.yml', 'pom.xml', 'package.json', 'package-lock.json', 'tsconfig.json', '.npmrc', 'cypress.config.ts', 'dockerfile', 'mvnw', 'mvnw.cmd'];
function pipelineFile(path) {
  const words = path.split(/[\\/]/).map(folded);
  const last = words.at(-1);
  return (
    words.some(gitish) ||
    words.some((w) => isName(w, '.mvn')) ||
    PIPELINE_DIRS.some((d) => isName(words[0], d)) ||
    PIPELINE_FILES.some((n) => isName(last, n)) ||
    /^cypress\.config\.[cm]?[jt]s$/.test(last) ||
    /^azure-.*\.yml$/.test(last) ||
    isName(last, 'azure-.yml')
  );
}

/** A repository of its own to read the crew's bundles in: bare, no template (no hooks), main in it for what to compare with. */
function openReader() {
  const dir = mkdtempSync(join(tmpdir(), 'suite-bundles-'));
  if (git('init', '-q', '--bare', '--template=', dir) === null || gitAt(dir, 'fetch', '-q', '--no-tags', ROOT, '+refs/remotes/origin/main:refs/heads/main') === null) {
    rmSync(dir, { recursive: true, force: true });
    throw new Stop("could not make a repository of its own to read the crew's bundles in.");
  }
  return dir;
}

/** The cards given back to the queue with one sentence naming what was refused; each only if Jira says this run still holds it. */
function turnBack(keys, why, seen) {
  for (const key of keys) {
    if (seen.has(key) || !KEY.test(key) || sync('holds', key).code !== 0) continue;
    seen.add(key);
    sync('unclaim', key, `the crew's work was refused: ${why}; another run may try.`);
    release(key);
    say(`${key}: refused: ${why}; back in the queue`);
  }
}

/**
 * Why a branch of the bundle (now `ref` in the reader) is refused, or null: not started from the commit the run claimed, no common
 * history, too many objects, a huge file, a path trick, a pipeline file changed, or one that differs from main's (an older main's
 * pipeline brought back).
 */
function branchProblem(ref, head, claimedBase) {
  const base = peek('merge-base', ref, 'refs/heads/main');
  if (!base) return `${head} has no history in common with main`;
  // The crew starts from the commit the run claimed. A branch from an older main carries that main's pipeline files, and a pipeline
  // runs from the tip it is pushed with; one from a newer main was not the crew's to start from.
  if (claimedBase && base !== claimedBase) return `${head} was not started from the commit this run claimed, ${claimedBase.slice(0, 12)}`;
  // How many objects the branch adds, before any name is read: the count is bounded by the output git is allowed to give.
  const ids = peekRaw(['rev-list', '--objects', '--no-object-names', ref, '^refs/heads/main'], undefined, (BUNDLE_OBJECTS_MAX + 1) * 41 + 1024);
  if (ids === null) return CUT_SHORT === 'ENOBUFS' ? `${head} adds more than ${BUNDLE_OBJECTS_MAX} objects` : couldNot(head);
  if (ids.split('\n').filter(Boolean).length > BUNDLE_OBJECTS_MAX) return `${head} adds more than ${BUNDLE_OBJECTS_MAX} objects`;
  // What the branch added, by size: a small file can unpack to much more than a bundle's size shows.
  const listed = peekRaw(['rev-list', '--objects', ref, '^refs/heads/main']);
  if (listed === null) return couldNot(head);
  const paths = new Map(listed.split('\n').filter(Boolean).map((l) => [l.slice(0, 40), l.slice(41)]));
  const sizes = peekRaw(['cat-file', '--batch-check=%(objectname) %(objectsize)'], `${[...paths.keys()].join('\n')}\n`);
  if (sizes === null) return couldNot(head);
  for (const line of sizes.split('\n')) {
    const [sha, size] = line.split(' ');
    if (Number(size) > BUNDLE_OBJECT_MAX_MB * 1048576)
      return `${head} holds "${plain(paths.get(sha) || sha)}" of ${Math.ceil(Number(size) / 1048576)} MB, past the ${BUNDLE_OBJECT_MAX_MB} MB a file may be`;
  }
  // What it changed against its merge base with main, however the crew built the commits: every path, deleted ones too.
  const diff = peekRaw(['diff-tree', '-r', '-t', '-z', '--no-renames', base, ref]);
  if (diff === null) return couldNot(head);
  const fields = diff.split('\0');
  const changed = [];
  for (let i = 0; i + 1 < fields.length; i += 2) {
    const [was, now] = fields[i].slice(1).split(' ');
    changed.push({ path: fields[i + 1], mode: now === '000000' ? was : now });
  }
  // A file is named before the folder it is in; a folder alone (an empty one) after.
  changed.sort((a, b) => Number(a.mode === '040000') - Number(b.mode === '040000'));
  for (const { path, mode } of changed) {
    const reason = trick(path, mode);
    if (reason) return `${head} holds the path "${plain(path)}", ${reason}`;
  }
  for (const { path } of changed) if (pipelineFile(path)) return `${head} changes "${plain(path)}", which the pipeline runs with the secrets`;
  // And the pipeline it would run is main's: no pipeline file of the branch differs from main's, whatever the branch's own changes were.
  const apart = peekRaw(['diff-tree', '-r', '--name-only', '-z', '--no-renames', 'refs/heads/main', ref]);
  if (apart === null) return couldNot(head);
  const differs = apart.split('\0').find((path) => path && pipelineFile(path));
  if (differs) return `${head} differs from main in "${plain(differs)}", which the pipeline runs with the secrets`;
  return null;
}

/**
 * One bundle read as data: the refs of its branches that are accepted, fetched into the reader as refs/run/<card>. The agent is the
 * folder it was uploaded in (bundle-<agent>/, as GitHub's download makes it; otherwise the file's own name), and the file must be named
 * <agent>.bundle: one agent never speaks for another. Refused whole (its agent's cards back in the queue, nothing fetched) when git
 * rejects it, it is huge, or it holds any ref but a stories/<card> one; a ref of a card this run does not hold for this agent is left;
 * a branch with a problem is refused alone.
 */
function takeBundle(bundle, claimed, seen) {
  const { stories, base: claimedBase } = claimed;
  const file = resolve(bundle);
  const name = basename(file);
  const shown = plain(name);
  const folder = basename(dirname(file));
  const agent = folder.startsWith('bundle-') ? folder.slice('bundle-'.length) : name.replace(/\.bundle$/, '');
  const theirs = stories.filter((s) => s.agent === agent).map((s) => s.key);
  const refuse = (why, more = []) => (turnBack([...theirs, ...more], why, seen), []);
  if (name !== `${agent}.bundle`) return refuse(`${shown} is not named ${plain(agent)}.bundle, as the bundle of the agent ${plain(agent)} must be`);
  const stat = lstatSync(file);
  if (!stat.isFile()) return refuse(`${shown} is not a plain file`);
  if (stat.size > BUNDLE_MAX_MB * 1048576) return refuse(`${shown} is ${Math.ceil(stat.size / 1048576)} MB, past the ${BUNDLE_MAX_MB} MB a bundle may be`);
  if (peek('bundle', 'verify', file) === null) return refuse(CUT_SHORT === 'ETIMEDOUT' ? couldNot(shown) : `git bundle verify rejects ${shown}`);
  const listing = peek('bundle', 'list-heads', file);
  if (listing === null) return refuse(couldNot(shown));
  const heads = listing.split('\n').filter(Boolean).map((l) => l.slice(l.indexOf(' ') + 1));
  const held = (ref) => stories.some((s) => s.key === ref.slice('refs/heads/stories/'.length) && s.agent === agent);
  const odd = heads.find((ref) => !ref.startsWith('refs/heads/stories/') || !KEY.test(ref.slice('refs/heads/stories/'.length)));
  if (odd) return refuse(`${shown} holds the ref "${plain(odd)}", and only refs/heads/stories/<card> of a card this run holds may come in`, heads.filter((r) => r !== odd && r.startsWith('refs/heads/stories/') && held(r)).map((r) => r.slice(19)));
  const mine = new Map();
  for (const head of heads) {
    const key = head.slice('refs/heads/stories/'.length);
    // Only a story this agent was given and Jira says this run holds: a bundle cannot name another card, nor another agent's.
    if (!held(head) || sync('holds', key).code !== 0 || seen.has(key)) {
      say(`${key}: not a story this run holds; left`);
      continue;
    }
    mine.set(key, head);
  }
  if (!mine.size) return [];
  // Objects checked as they come in (fsck): a malformed one is refused. The path tricks fsck knows are named by the reading below instead.
  const fsck = [['transfer.fsckObjects', 'true'], ...FSCK_PATHS.map((id) => [`fsck.${id}`, 'ignore'])];
  if (peekRaw(['fetch', '-q', '--no-tags', file, ...[...mine].map(([key, head]) => `+${head}:refs/run/${key}`)], undefined, undefined, fsck) === null) return refuse(couldNot(shown));
  // git does not check the objects of a bundle as it unpacks it, whatever transfer.fsckObjects says: so it is asked to, once they are in.
  if (peekRaw(['fsck', '--strict', '--no-dangling', '--no-progress'], undefined, undefined, fsck) === null) return (say(`git fsck said: ${GIT_SAID}`), refuse(CUT_SHORT === 'ETIMEDOUT' ? couldNot(shown) : `git fsck rejects the objects of ${shown}`));
  const taken = [];
  for (const [key, head] of mine) {
    const why = branchProblem(`refs/run/${key}`, head, claimedBase);
    if (why) turnBack([key], why, seen);
    else {
      seen.add(key);
      taken.push(`refs/run/${key}`);
    }
  }
  return taken;
}

/** The fsck messages about names in a tree, which branchProblem reads from the diff and refuses with the path in its sentence. */
const FSCK_PATHS = ['hasDot', 'hasDotdot', 'hasDotgit', 'fullPathname', 'emptyName', 'gitmodulesSymlink', 'gitmodulesName'];

/** publish: each story of the bundles, from data only: locked, pushed and proposed, reported, or put back in the queue. */
async function publish(bundles, isolated = true) {
  ISOLATED = isolated;
  checkCommands();
  git('fetch', '-q', 'origin', 'main');
  READER = openReader();
  try {
    return await publishFrom(bundles);
  } finally {
    rmSync(READER, { recursive: true, force: true });
    READER = null;
  }
}

async function publishFrom(bundles) {
  const claimed = readClaimed();
  const { stories } = claimed;
  const seen = new Set();
  // The crew's branches on the remote as this run saw them, before any push: a push replaces only what it saw (--force-with-lease).
  const lastSeen = new Map((git('ls-remote', 'origin', 'refs/heads/stories/*') ?? '').split('\n').filter(Boolean).map((l) => l.split('\t').reverse()));
  const refs = bundles.filter((b) => existsSync(b)).flatMap((b) => takeBundle(b, claimed, seen));
  for (const ref of refs) {
    const key = ref.slice('refs/run/'.length);
    const title = (peek('log', '-1', '--format=%s', ref) ?? key).replace(/^[^:]*:\s*/, '');
    const said = /^Outcome: (.+)$/m.exec(peek('log', '-1', '--format=%B', ref) ?? '')?.[1] ?? 'nothing';
    const outcome = decidedIn(ref, key, said);
    const values = { key, title, branch: `stories/${key}` };
    if (outcome === 'implemented') {
      const base = peek('merge-base', ref, 'refs/heads/main');
      const shared = base ? sharedSince(base, ref) : [];
      if (!(await lockAll(shared, key))) {
        sync('unclaim', key, `another story held ${shared.join(', ')} past ${WAIT_MS / 60_000} minutes; done again on a newer main.`);
        release(key);
        say(`${key}: a shared file is held; back in the queue`);
        continue;
      }
      const moved = shared.length && base ? peek('diff', '--name-only', base, 'refs/heads/main', '--', ...shared) : '';
      if (moved) {
        sync('unclaim', key, `${moved.split('\n').join(', ')} changed on main meanwhile; done again on top of it.`);
        release(key);
        say(`${key}: changed on main meanwhile; back in the queue`);
        continue;
      }
      // GitLab opens its merge request from the push itself: SUITE_PUSH_OPTIONS, one a line, its {names} filled in (no shell).
      const options = (process.env.SUITE_PUSH_OPTIONS ?? '').split('\n').filter(Boolean)
        .flatMap((o) => ['-o', o.replace(/\{(\w+)\}/g, (_, k) => String(values[k] ?? '').replace(/[\r\n]+/g, ' '))]);
      // From the reader, which holds the objects (this checkout never does), to the remote this checkout pushes to; the branch is replaced
      // only if it is still what this run saw: another run's work on the card is never overwritten (an empty value: it must not exist).
      // The commit the tip names (a tag object as a tip is peeled: a branch holds a commit).
      const remote = git('remote', 'get-url', '--push', 'origin');
      const commit = peek('rev-parse', '--verify', `${ref}^{commit}`);
      const lease = `--force-with-lease=refs/heads/${values.branch}:${lastSeen.get(`refs/heads/${values.branch}`) ?? ''}`;
      if (!remote || !commit || peek('push', '-q', lease, ...options, remote, `${commit}:refs/heads/${values.branch}`) === null) {
        // The locks this card took are freed and the card goes back: another run may try on the newer branch.
        sync('unclaim', key, 'the push was refused (the branch changed on the remote since this run looked, or the remote said no); another run may try.');
        release(key);
        say(`${key}: push failed; back in the queue`);
        continue;
      }
      if (process.env.SUITE_PROPOSE) shell(process.env.SUITE_PROPOSE, values);
      sync('note', key, `Tests proposed: branch ${values.branch}. The card moves to done when it merges.`);
      say(`${key}: proposed as ${values.branch}`);
    } else if (outcome === 'pushed back' || outcome === 'waiting') {
      // The story's own files from the branch, as data: the pushback or the questions, reported from them.
      const own = (peek('diff', '--name-only', '--diff-filter=AM', peek('merge-base', ref, 'refs/heads/main') ?? 'refs/heads/main', ref, '--', 'stories/') ?? '')
        .split('\n')
        .filter((f) => f && storyOf([basename(f)], key));
      for (const f of own) {
        mkdirSync(dirname(join(ROOT, f)), { recursive: true });
        writeFileSync(join(ROOT, f), peek('show', `${ref}:${f}`) ?? '');
      }
      sync('report', key);
      resetTo('origin/main');
      release(key);
      say(`${key}: ${outcome}; reported`);
    } else {
      sync('unclaim', key, outcome === 'checks failed' ? "the suite's checks failed on the crew's tests; another run may try." : 'the crew decided nothing; another run may try.');
      release(key);
      say(`${key}: ${outcome}; back in the queue`);
    }
  }
  // A story claimed with no branch (its crew job stopped): back in the queue.
  for (const { key } of stories) {
    if (seen.has(key) || !KEY.test(key) || sync('holds', key).code !== 0) continue;
    sync('unclaim', key, 'its crew job stopped before it finished; another run may take it.');
    release(key);
    say(`${key}: no branch from its crew; back in the queue`);
  }
  say(seen.size ? `${seen.size} ${seen.size === 1 ? 'story' : 'stories'} from the bundles dealt with` : 'nothing to publish: no bundle held a story');
  const left = sync('queue');
  // Jira set up but not answering, or refusing the account: said, and the run is red. Not set up at all: its sentence, and nothing to do.
  if (left.code !== 0) {
    say(left.out);
    return 1;
  }
  if (!left.out.startsWith('[')) say(left.out);
  if (left.out.startsWith('[{') && process.env.SUITE_AGAIN) {
    say('stories are left: the next run started');
    shell(process.env.SUITE_AGAIN, {});
  }
  return 0;
}

/** work: the three, one after another, in this folder (a person's computer, where the crew runs as them anyway). */
async function work() {
  // Each story three times at most a run of work: one put back in the queue more often waits for the next.
  const tried = new Map();
  let until = Date.now() + WAIT_MS;
  for (;;) {
    process.env.SUITE_AGENTS = '1';
    if (claim((key) => (tried.get(key) ?? 0) >= 3) !== 0) return 1;
    const claimed = readClaimed();
    // Stories ready but waiting on pages others hold: waited for, up to SUITE_WAIT_MINUTES with nothing taken.
    if (!claimed.stories.length && claimed.blocked && Date.now() < until) {
      await sleep(POLL_MS);
      continue;
    }
    if (!claimed.stories.length) break;
    until = Date.now() + WAIT_MS;
    for (const s of claimed.stories) {
      s.agent = AGENT;
      tried.set(s.key, (tried.get(s.key) ?? 0) + 1);
    }
    writeFileSync(CLAIMED, `${JSON.stringify(claimed, null, 2)}\n`);
    if (crew() !== 0) return 1;
    await publish([join(RUN, `${AGENT}.bundle`)], false);
    rmSync(RUN, { recursive: true, force: true });
  }
  say(`done: ${tried.size ? `${tried.size} ${tried.size === 1 ? 'story' : 'stories'} worked on` : 'nothing to take'}. Thank you.`);
  return 0;
}

/** On main after a merge: each story merged reported done in Jira, and its locks freed. */
function merged() {
  // pending reads the story files and asks Jira nothing; with nothing set up it answers an empty list and says so (exit 0).
  const asked = sync('pending');
  if (asked.code !== 0) {
    say(asked.out);
    return asked.code;
  }
  let pending;
  try {
    pending = JSON.parse(asked.json || '[]');
  } catch {
    say(`jira-loop/sync.mjs pending did not answer in JSON: ${asked.out.slice(0, 200)}`);
    return 1;
  }
  const report = sync('report');
  console.log(report.out);
  for (const p of pending) if (p.done) release(p.key);
  // Its pages free now: the stories that waited on them are taken by the next run.
  const freed = pending.some((p) => p.done);
  if (freed && process.env.SUITE_AGAIN && sync('queue').out.startsWith('[{')) shell(process.env.SUITE_AGAIN, {});
  return report.code;
}

const [command, ...args] = process.argv.slice(2);
try {
  if (command === 'claim') process.exitCode = claim();
  else if (command === 'crew') process.exitCode = crew();
  else if (command === 'publish') process.exitCode = await publish(args);
  else if (command === 'work') process.exitCode = await work();
  else if (command === 'merged') process.exitCode = merged();
  else if (command === 'need' && args[0] && process.env.SUITE_STORY) {
    // The crew, before changing a file that already exists and other stories may change too: the locks as the
    // run found them (the crew has no credential to ask git); the lock itself is taken when the story is published.
    const file = args[0];
    const holder = readClaimed().held.find((h) => h.file === file && h.key !== process.env.SUITE_STORY)?.key ?? null;
    console.log(holder ? `${file}: held by ${holder}: change something else, or finish without it and say so.` : `${file}: yours, unless another story takes it first (the lock is taken when this one is published).`);
    process.exitCode = holder ? 2 : 0;
  } else if (command === 'locks') {
    const held = locks();
    for (const l of held) console.log(`${l.file}  ${l.key}  since ${new Date(l.at).toISOString()}`);
    if (!held.length) say('no lock is held (or this folder has no origin to read them from)');
  } else {
    console.log('node jira-loop/agents.mjs claim | crew | publish <bundle ...> | work | merged | need <file> | locks   (what each does: the top of this file)');
    process.exitCode = command ? 1 : 0;
  }
} catch (e) {
  if (!(e instanceof Stop)) throw e;
  say(e.message);
  process.exitCode = 1;
}
